import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int left = sc.nextInt();

        while (left > 0) {
            System.out.println("还剩 " + left + " 条喵");
            left = left - 1;
        }

        System.out.println("发完啦");
    }
}

